test_suite:
test('createUserId returns a string at runtime', () => {
  const uid = createUserId('user-123');
  expect(typeof uid).toBe('string');
  expect(uid).toBe('user-123');
});

test('createPostId returns a string at runtime', () => {
  const pid = createPostId('post-456');
  expect(typeof pid).toBe('string');
  expect(pid).toBe('post-456');
});

test('type-level: UserId extends string', () => {
  type Check = UserId extends string ? true : false;
  const check: Check = true;
  expect(check).toBe(true);
});

test('type-level: UserId is not assignable to PostId', () => {
  type Check = UserId extends PostId ? true : false;
  const check: Check = false;
  expect(check).toBe(false);
});

// __hidden__
test('type-level: PostId is not assignable to UserId', () => {
  type Check = PostId extends UserId ? true : false;
  const check: Check = false;
  expect(check).toBe(false);
});

solution:
export type Brand<T, B> = T & { readonly __brand: B };
export type UserId = Brand<string, 'UserId'>;
export type PostId = Brand<string, 'PostId'>;

export function createUserId(s: string): UserId {
  return s as UserId;
}

export function createPostId(s: string): PostId {
  return s as PostId;
}
